<?php require_once 'bootstrap.php';$u=require_login();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$date=$_POST['sobriety_start_date']??'';if($date){db()->prepare('UPDATE users SET sobriety_start_date=? WHERE sic_id=?')->execute([$date,$u['sic_id']]);db()->prepare('INSERT INTO sobriety_records(sic_id,user_sic_id,start_date,current_streak,lifetime_days) VALUES(?,?,?,0,0) ON CONFLICT(user_sic_id) DO UPDATE SET start_date=excluded.start_date,updated_at=CURRENT_TIMESTAMP')->execute([sic_id(),$u['sic_id'],$date]);$msg='Data del percorso aggiornata. La storia DRX precedente non viene cancellata.';}}$u=current_user();$sync=sobriety_sync($u['sic_id']);db()->prepare('UPDATE sobriety_records SET current_streak=?,lifetime_days=MAX(lifetime_days,?),updated_at=CURRENT_TIMESTAMP WHERE user_sic_id=?')->execute([$sync['days'],$sync['days'],$u['sic_id']]);$ms=db()->query('SELECT * FROM sobriety_milestones ORDER BY days')->fetchAll();$pageTitle='Cammino';require '_header.php';?><section class="section-head"><div><span class="eyebrow">Sobriety Journey</span><h1>Un giorno alla volta.</h1><p>Ogni giorno di sobrietà genera 1 DRX. Una difficoltà non cancella DRX, rank o storia già costruita.</p></div></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><section class="card"><h2>Il mio contatore</h2><p class="big-number"><?=number_format($sync['days'],0,',','.')?> giorni</p><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><label>Data di inizio del percorso<input type="date" name="sobriety_start_date" value="<?=h($u['sobriety_start_date']??'')?>" max="<?=date('Y-m-d')?>"></label><button class="btn">Aggiorna</button></form></section><section class="rank-road"><?php foreach($ms as $m):?><div class="rank-step"><b><?=number_format($m['days'],0,',','.')?> · <?=h($m['title'])?></b><span>+<?=number_format($m['drx_reward'],0,',','.')?> DRX</span></div><?php endforeach;?></section><?php require '_footer.php';?>